css:
body {
  margin: 0;
  font-family: Arial, sans-serif;
  background-color: #f3e5f5;
}

#homepage {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
  background-color: #f3e5f5;
}

.link-container {
  margin: 20px;
  padding: 40px;
  background: linear-gradient(45deg, #7b1fa2, #ff7043);
  border-radius: 12px;
  width: 300px;
  text-align: center;
  transition: transform 0.3s;
}

.link-container:hover {
  transform: scale(1.05);
}

.link {
  color: white;
  text-decoration: none;
  font-size: 22px;
}

